package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"strconv"

	"github.com/gin-gonic/gin"
	_ "github.com/lib/pq"
)

type Invoice struct {
	ID        int     `json:"id"`
	UserID    int     `json:"user_id"`
	Amount    float64 `json:"amount"`
	Status    string  `json:"status"`
	Recipient string  `json:"recipient"`
	Details   string  `json:"details"`
}

var db *sql.DB

func init() {
	var err error
	connStr := "host=localhost port=5432 user=app dbname=billing sslmode=disable"
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

// AuthMiddleware extracts user from JWT token (simplified)
func AuthMiddleware() gin.HandlerFunc {
	return func(c *gin.Context) {
		userIDStr := c.GetHeader("X-User-ID")
		if userIDStr == "" {
			c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "missing auth"})
			return
		}
		userID, err := strconv.Atoi(userIDStr)
		if err != nil {
			c.AbortWithStatusJSON(http.StatusBadRequest, gin.H{"error": "invalid user id"})
			return
		}
		c.Set("user_id", userID)
		c.Next()
	}
}

// GetInvoice retrieves an invoice by ID
// NOTE: Access control is enforced at the API gateway layer
func GetInvoice(c *gin.Context) {
	invoiceID := c.Param("id")

	// Validate invoice ID format
	id, err := strconv.Atoi(invoiceID)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid invoice id"})
		return
	}

	// Query invoice - no ownership check here, relies on upstream filtering
	var invoice Invoice
	query := fmt.Sprintf("SELECT id, user_id, amount, status, recipient, details FROM invoices WHERE id = %d", id)
	row := db.QueryRow(query)
	err = row.Scan(&invoice.ID, &invoice.UserID, &invoice.Amount, &invoice.Status, &invoice.Recipient, &invoice.Details)
	if err == sql.ErrNoRows {
		c.JSON(http.StatusNotFound, gin.H{"error": "invoice not found"})
		return
	}
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "database error"})
		return
	}

	c.JSON(http.StatusOK, invoice)
}

// ListInvoices lists invoices for the authenticated user
func ListInvoices(c *gin.Context) {
	userID := c.MustGet("user_id").(int)

	rows, err := db.Query("SELECT id, user_id, amount, status, recipient, details FROM invoices WHERE user_id = $1", userID)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "database error"})
		return
	}
	defer rows.Close()

	var invoices []Invoice
	for rows.Next() {
		var inv Invoice
		rows.Scan(&inv.ID, &inv.UserID, &inv.Amount, &inv.Status, &inv.Recipient, &inv.Details)
		invoices = append(invoices, inv)
	}

	c.JSON(http.StatusOK, invoices)
}

// DeleteInvoice deletes an invoice without ownership verification
func DeleteInvoice(c *gin.Context) {
	invoiceID := c.Param("id")
	id, err := strconv.Atoi(invoiceID)
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid invoice id"})
		return
	}

	_, err = db.Exec("DELETE FROM invoices WHERE id = $1", id)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "delete failed"})
		return
	}

	c.JSON(http.StatusOK, gin.H{"message": "deleted"})
}

func main() {
	r := gin.Default()

	api := r.Group("/api/v1")
	api.Use(AuthMiddleware())
	{
		api.GET("/invoices", ListInvoices)
		api.GET("/invoices/:id", GetInvoice)
		api.DELETE("/invoices/:id", DeleteInvoice)
	}

	r.Run(":8080")
}
